sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        // Get the category parameter from the request body
        var requestBody = request.body ? request.body.data : {};
        var categoryFilter = requestBody.category || null;

        gs.info('REST API received category filter: ' + categoryFilter);

        // Create task builder and pass the category filter
        var taskBuilder = new CreateRunOnboardValueBuilderTask();
        var result = taskBuilder.createOrUpdateTasks(categoryFilter);

        // Log processed information
        gs.info('Created Tasks: ' + JSON.stringify(result.createdTasks));
        gs.info('Updated Tasks: ' + JSON.stringify(result.updatedTasks));
        gs.info('Processed Properties: ' + JSON.stringify(result.processedProperties));

        response.setStatus(200);
        response.setBody({
            status: "success",
            message: categoryFilter ? 
                "Tasks for category '" + categoryFilter + "' processed successfully." : 
                "All tasks processed successfully.",
            created_tasks: result.createdTasks,
            updated_tasks: result.updatedTasks,
            processed_properties: result.processedProperties.length ? 
                result.processedProperties : ["No properties processed."],
            category_processed: categoryFilter || "All categories"
        });

    } catch (error) {
        gs.error("Error executing CreateRunOnboardValueBuilderTask: " + error.message);
        response.setStatus(500);
        response.setBody({
            status: "error",
            message: "An error occurred while processing tasks: " + error.message
        });
    }
})(request, response);
